/* Frame-level atmosphere, shared by previews and exports. */
(function(){'use strict';const M=Motion;const types=['rain','snow','wind','fog','dust','falling-leaves','confetti','stars'];const mod=(n,m)=>(n%m+m)%m;
function render(c,f,t){const fx=f.sceneEffects;if(!fx?.types?.length)return;const strength=Math.max(0,Math.min(1,fx.intensity??.6)),speed=Math.max(.1,Math.min(3,fx.speed??1)),direction=Math.max(-1,Math.min(1,fx.direction??.3)),time=((f.localTime??t)+(fx.timeOffset||0))*speed;c.save();c.setTransform(c.canvas.width/1920,0,0,c.canvas.height/1080,0,0);c.beginPath();c.rect(0,0,1920,1080);c.clip();c.globalAlpha=strength;for(const type of fx.types){if(!types.includes(type))continue;const count=type==='fog'?12:Math.round(30+strength*130);for(let i=0;i<count;i++){const seed=mod(Math.sin(i*127.1+4)*43758.5453,1),seed2=mod(Math.sin(i*311.7+9)*23421.135,1),x=mod(seed*2120+time*(type==='wind'?400:90)*direction,2120)-100,y=mod(seed2*1280+time*(type==='rain'?650:type==='snow'?85:type==='wind'?0:35),1280)-100;c.save();c.lineWidth=2;c.strokeStyle='#d5e8ed';c.fillStyle='#f4f6f7';if(type==='rain')M.line(c,[[x,y],[x-direction*26,y+36]],'#a7cbdc',2);else if(type==='snow')M.ellipse(c,x+Math.sin(time+i)*18,y,2+seed*5,2+seed*5,'#f8fafc');else if(type==='wind'){c.globalAlpha*=.45;c.beginPath();c.moveTo(x,y);c.bezierCurveTo(x+70,y-25,x+130,y+30,x+210,y);c.stroke()}else if(type==='fog'){const g=c.createRadialGradient(x,y,0,x,y,360);g.addColorStop(0,'#dae1e675');g.addColorStop(1,'#dae1e600');c.fillStyle=g;c.fillRect(x-360,y-360,720,720)}else if(type==='dust')M.ellipse(c,x,y,1+seed*4,1+seed*4,'#d2bd8a');else if(type==='stars'){c.globalAlpha*=.3+.7*(.5+.5*Math.sin(time*2+i));M.line(c,[[x-5,y],[x+5,y]],'#fff0bd',2);M.line(c,[[x,y-5],[x,y+5]],'#fff0bd',2)}else{c.translate(x,y);c.rotate(time+i);c.fillStyle=type==='falling-leaves'?['#a9a364','#c68f50','#829b68'][i%3]:['#e7838a','#e5c362','#79bfb1','#a89bdd'][i%4];if(type==='falling-leaves')M.ellipse(c,0,0,12,5,c.fillStyle);else c.fillRect(-5,-3,10,6)}c.restore()}}c.restore()}
M.weather={types,render};})();
